const $=id=>document.getElementById(id),reviews=JSON.parse(localStorage.getItem('leadReviews')||'{}');let leads=[];
const key=l=>`${l.type}/${l.id}`,site=l=>l.tags.website||l.tags['contact:website']||l.tags.url||l.tags['contact:url'];
const state=l=>reviews[key(l)]||(site(l)?'website':'unlisted');
function review(l,value){reviews[key(l)]=value;localStorage.setItem('leadReviews',JSON.stringify(reviews));render()}
function render(){let box=$('cards'),mode=$('filter').value;box.replaceChildren();let shown=leads.filter(l=>mode==='all'||state(l)===mode);$('status').textContent=`${shown.length} shown of ${leads.length} listings`;for(let l of shown){let c=document.createElement('article');c.className='card';let h=document.createElement('h3');h.textContent=l.tags.name;let badge=document.createElement('p');badge.className='tag';badge.textContent={unlisted:'No website listed — check it',verified:'Checked: no website found',website:'Website listed or found'}[state(l)];let address=document.createElement('p');address.className='muted';address.textContent=[l.tags['addr:housenumber'],l.tags['addr:street']].filter(Boolean).join(' ')||'Address not listed';let check=document.createElement('a');check.href='https://www.google.com/search?q='+encodeURIComponent(`${l.tags.name} ${$('place').value} website`);check.target='_blank';check.rel='noopener';check.textContent='Check for a website';c.append(h,badge,address,check);if(site(l)){let p=document.createElement('p'),a=document.createElement('a');a.href=/^https?:\/\//i.test(site(l))?site(l):'https://'+site(l);a.target='_blank';a.rel='noopener';a.textContent='Visit listed website';p.append(a);c.append(p)}let controls=document.createElement('p');for(let [label,value] of [['Website found','website'],['Checked: none found','verified'],['Reset review','unlisted']]){let b=document.createElement('button');b.textContent=label;b.onclick=()=>review(l,value);controls.append(b)}let draft=document.createElement('button');draft.textContent='Draft email';draft.onclick=()=>draftEmail(l);controls.append(draft);c.append(controls);box.append(c)}}
async function overpass(query){let error;for(let host of ['https://overpass-api.de/api/interpreter','https://overpass.kumi.systems/api/interpreter']){try{let r=await fetch(host+'?data='+encodeURIComponent(query));if(!r.ok)throw Error(`Map service returned ${r.status}`);return await r.json()}catch(e){error=e}}throw error}
$('search').onclick=async()=>{let place=$('place').value.trim();if(!place){$('status').textContent='Enter a location.';return}$('status').textContent='Searching…';$('cards').replaceChildren();try{let geo=await(await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=us&q='+encodeURIComponent(place))).json();if(!geo.length)throw Error('Location not found');let {lat,lon}=geo[0],area=`(around:5000,${lat},${lon})`,kind=$('kind').value,tags=['shop','amenity','office','craft','healthcare','tourism','leisure'];let clauses=tags.map(t=>kind==='all'?`nwr["name"]["${t}"]${area};`:`nwr["name"]["${t}"="${kind}"]${area};`);let data=await overpass(`[out:json][timeout:30];(${clauses.join('')});out center 200;`);leads=(data.elements||[]).filter(e=>e.tags?.name&&!e.tags.disused&&!e.tags.abandoned&&!e.tags.closed);leads.sort((a,b)=>Number(!!site(a))-Number(!!site(b)));render()}catch(e){$('status').textContent='Search unavailable: '+e.message}};
$('filter').onchange=render;
function draftEmail(l){let name=l.tags.name,sender=$('sender').value.trim()||'[your business]';$('email').value=`Subject: A website idea for ${name}\n\nHi ${name} team,\n\nI came across your business while looking at local businesses in ${$('place').value}. [Add one real, specific detail you noticed.]\n\nI'm with ${sender}. We create clear, mobile-friendly websites that help local customers find what they need and get in touch. I'd love to share a few ideas tailored to ${name}.\n\nWould you be open to a brief conversation next week?\n\nBest,\n[Your name]\n${sender}`;$('email').scrollIntoView({behavior:'smooth'})}
$('copy').onclick=async()=>{await navigator.clipboard.writeText($('email').value);$('copy').textContent='Copied!';setTimeout(()=>$('copy').textContent='Copy email',1500)};

